<?php
require_role('siswa');
$periodId=isset($_GET['id_tahun_ajaran'])?input_id($_GET,'id_tahun_ajaran'):(int)active_period()['id_tahun_ajaran'];$period=ak_period($periodId);
$month=input_text(['bulan'=>$_GET['bulan']??date('Y-m')],'bulan',7);if(!preg_match('/^[0-9]{4}-(0[1-9]|1[0-2])$/D',$month))throw new InputError('Bulan tidak valid.');
$from=max($period['mulai'],$month.'-01');$until=min($period['selesai'],(new DateTimeImmutable($month.'-01'))->modify('last day of this month')->format('Y-m-d'),date('Y-m-d'));
$rows=ak_rows('SELECT a.*,k.nama_kelas FROM ak_anggota_kelas a JOIN kelas k ON k.id_kelas=a.id_kelas WHERE a.nis=? AND a.id_tahun_ajaran=? AND a.mulai<=? AND a.selesai>=?',[(string)user_reference(),$periodId,$until,$from]);
$stored=[];foreach(ak_rows('SELECT tanggal,status,keterangan FROM ak_absensi_harian WHERE nis=? AND id_tahun_ajaran=? AND tanggal BETWEEN ? AND ?',[(string)user_reference(),$periodId,$from,$until]) as $row)$stored[$row['tanggal']]=$row;
$daily=[];if($from<=$until)for($d=new DateTimeImmutable($from);$d->format('Y-m-d')<=$until;$d=$d->modify('+1 day'))foreach($rows as $membership)if($membership['mulai']<=$d->format('Y-m-d')&&$membership['selesai']>=$d->format('Y-m-d')&&ak_school_day($period,$d->format('Y-m-d'))){$day=$d->format('Y-m-d');$daily[]=['tanggal'=>$day,'kelas'=>$membership['nama_kelas'],'status'=>$stored[$day]['status']??'B','keterangan'=>$stored[$day]['keterangan']??'Belum ada rekap harian terverifikasi'];}
?><form method="get" class="panel form-grid filter"><?php ak_hidden('view','kehadiran');ak_hidden('id_tahun_ajaran',$periodId);ak_field('bulan','Bulan',$month,'month');?><button class="secondary">Tampilkan</button></form><section class="panel"><h2>Kehadiran saya</h2><p>Rekap harian sekolah dari hasil pemeriksaan Guru Piket. Hari efektif yang belum terverifikasi tetap Belum Dikonfirmasi.</p><?php ak_summary_cards(ak_summary($daily));foreach(array_reverse($daily) as $row):?><article class="history-entry"><strong><?=e($row['tanggal'])?> · <?=e(AK_STATUSES[$row['status']])?></strong><p><?=e($row['kelas'])?> · <?=e($row['keterangan'])?></p></article><?php endforeach;if(!$daily):?><p>Tidak ada keanggotaan atau hari efektif pada rentang ini.</p><?php endif;?></section>
